    /**
     * Method to retrieve the Merchant via an FindMerchantQuery
     * @return 	query	FindMerchantQuery
     */
    @SuppressWarnings("unused")
    public Merchant find( UUID id ) {
    	LOGGER.info("handling find using " + id.toString() );
    	try {
    		return repository.findById(id).get();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find a Merchant - {0}", exc.getMessage() );
    	}
    	return null;
    }
    
    /**
     * Method to retrieve a collection of all Merchants
     *
     * @param	query	FindAllMerchantQuery 
     * @return 	List<Merchant> 
     */
    @SuppressWarnings("unused")
    public List<Merchant> findAll( FindAllMerchantQuery query ) {
    	LOGGER.info("handling findAll using " + query.toString() );
    	try {
    		return repository.findAll();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find all Merchant - {0}", exc.getMessage() );
    	}
    	return null;
    }


